// ─── File: BehavioralDemo.java ───
package com.bank.behavioral;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class BehavioralDemo {
    private static final Logger log = Logger.getLogger(BehavioralDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // OBSERVER
        TransferPublisher publisher = new TransferPublisher();
        publisher.subscribe(e -> Logger.getLogger("AUDIT").info("audit: " + e));
        publisher.subscribe(e -> Logger.getLogger("SMS").info("sms: " + e));
        publisher.publish("TRANSFER SAV2001->CUR3001 Rs.50000");

        // COMMAND (with undo)
        StatefulAccount rajesh = new StatefulAccount("SAV2001", new BigDecimal("1000000"));
        StatefulAccount priya  = new StatefulAccount("CUR3001", new BigDecimal("250000"));
        CommandInvoker invoker = new CommandInvoker();
        invoker.run(new DebitCommand(rajesh, new BigDecimal("50000")));
        invoker.run(new CreditCommand(priya, new BigDecimal("50000")));
        log.info(() -> "After commands: Rajesh=" + rajesh.balance() + " Priya=" + priya.balance());
        invoker.undoLast();  // reverse the credit
        invoker.undoLast();  // reverse the debit
        log.info(() -> "After undo: Rajesh=" + rajesh.balance() + " Priya=" + priya.balance());

        // STATE
        rajesh.withdraw(new BigDecimal("10000"));   // ACTIVE → allowed
        rajesh.freeze();
        try { rajesh.withdraw(new BigDecimal("10000")); }  // FROZEN → blocked
        catch (IllegalStateException e) { log.warning("Withdraw blocked: " + e.getMessage()); }

        // TEMPLATE METHOD
        SettlementTemplate settlement = new EquitySettlement();
        settlement.settle("TRD-1001");
    }
}

// ─── OBSERVER ───
interface TransferListener { void onEvent(String event); }
class TransferPublisher {
    private final List<TransferListener> listeners = new ArrayList<>();
    void subscribe(TransferListener l){ listeners.add(l); }
    void publish(String e){ listeners.forEach(l -> l.onEvent(e)); }
}

// ─── COMMAND ───
interface Command { void execute(); void undo(); }
class DebitCommand implements Command {
    private final StatefulAccount acct; private final BigDecimal amt;
    DebitCommand(StatefulAccount a, BigDecimal m){ acct=a; amt=m; }
    public void execute(){ acct.debit(amt); } public void undo(){ acct.credit(amt); }
}
class CreditCommand implements Command {
    private final StatefulAccount acct; private final BigDecimal amt;
    CreditCommand(StatefulAccount a, BigDecimal m){ acct=a; amt=m; }
    public void execute(){ acct.credit(amt); } public void undo(){ acct.debit(amt); }
}
class CommandInvoker {
    private final Deque<Command> history = new ArrayDeque<>();
    void run(Command c){ c.execute(); history.push(c); }
    void undoLast(){ if(!history.isEmpty()) history.pop().undo(); }
}

// ─── STATE ───
interface AccountState { void withdraw(StatefulAccount a, BigDecimal amt); }
class ActiveState implements AccountState {
    public void withdraw(StatefulAccount a, BigDecimal amt){ a.debit(amt); }
}
class FrozenState implements AccountState {
    public void withdraw(StatefulAccount a, BigDecimal amt){ throw new IllegalStateException("Account frozen"); }
}
class StatefulAccount {
    private final String id; private BigDecimal balance; private AccountState state = new ActiveState();
        StatefulAccount(String id, BigDecimal bal){ this.id=id;
        this.balance=bal; }
    void debit(BigDecimal a){ balance = balance.subtract(a); }
    void credit(BigDecimal a){ balance = balance.add(a); }
    void withdraw(BigDecimal a){ state.withdraw(this, a); }
    void freeze(){ state = new FrozenState(); }
    void activate(){ state = new ActiveState(); }
    BigDecimal balance(){ return balance; }
}

// ─── TEMPLATE METHOD ───
abstract class SettlementTemplate {
    private static final Logger log = Logger.getLogger(SettlementTemplate.class.getName());
    final void settle(String tradeId) {           // skeleton is fixed
        validate(tradeId);
        execute(tradeId);                           // the only varying step
        record(tradeId);
    }
    private void validate(String id){ log.info(() -> "validate " + id); }
    protected abstract void execute(String id);     // subclasses fill this
    private void record(String id){ log.info(() -> "record " + id); }
}
class EquitySettlement extends SettlementTemplate {
    protected void execute(String id){ Logger.getLogger("SETTLE").info("execute equity T+1 " + id); }
}

class BankLogFormatter extends Formatter {
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
